// Rebuild the publish loader from the same sources used by `lua main.lua`.
// No npm dependencies; run `node tools/bundle_loader.js [--check]`.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const read = name => fs.readFileSync(path.join(root, name), 'utf8').replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');
function literal(source) {
  let eq = '';
  while (source.includes(`]${eq}]`)) eq += '=';
  return `[${eq}[\n${source}]${eq}]`;
}
const files = ['config/template.lua', 'scripts/rejoin_heartbeat.lua'];
for (const folder of ['core', 'managers', 'utils']) {
  for (const file of fs.readdirSync(path.join(root, folder)).sort()) {
    if (file.endsWith('.lua')) files.push(`${folder}/${file}`);
  }
}
files.sort();
const modules = files.map(name => {
  const id = name.replace(/\.lua$/, '').replace(/\//g, '.');
  return `__ya_sources[${JSON.stringify(id)}] = ${literal(read(name))}\n`;
}).join('\n');
const output = `--[[
  yanamin.lua — Rejoin Engine publish loader.
  Generated by tools/bundle_loader.js; edit sources and rebuild.
  Source: https://github.com/apengjers/rejoin
  Bundled: ${files.length} modules, entry main.lua.
  State: /sdcard/yanamin (override with YANAMIN_HOME).
]]
local __ya_sources = {}
${modules}
${read('tools/bundle_runtime.lua')}
-- Entry point (main.lua)
${read('main.lua')}`;
const target = path.join(root, 'yanamin.lua');
if (process.argv.includes('--check')) {
  if (!fs.existsSync(target) || read('yanamin.lua') !== output) {
    console.error('yanamin.lua is stale; run node tools/bundle_loader.js');
    process.exit(1);
  }
  console.log(`Bundle matches ${files.length} source modules and main.lua`);
} else {
  fs.writeFileSync(target, output);
  console.log(`Built yanamin.lua (${files.length} modules)`);
}
